  <button onclick="nextStep()">▶</button>
</span>
<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
(function () {
  var ORANGE = '#E8663C', NAVY = '#12457A', AXIS = '#111111', GRAY = '#A8AEB6';
  var draw = SVG().addTo(document.getElementById('container')).size('100%', '100%');

  var a = 4, b = 3, triView = false;
  var XH = 9, YH = 7.2, UNIT = 30, FS = 14;

  function fmt(v) { return String(Math.round(v * 100) / 100); }
  function sgn(v) { return v < 0 ? -1 : 1; }

  function innerSize() {
    if (typeof _containerInnerSize === 'function') return _containerInnerSize();
    var el = document.getElementById('container');
    return { width: el.clientWidth, height: el.clientHeight };
  }

  function configure() {
    var s = innerSize();
    var w = Math.max(160, s.width || 640), h = Math.max(120, s.height || 460);
    var m = Math.max(10, Math.min(26, Math.min(w, h) * 0.05));
    var iw = w - 2 * m, ih = h - 2 * m;
    var base = 7.4;
    if (iw >= ih) { YH = base; XH = base * iw / ih; }
    else { XH = base; YH = base * ih / iw; }
    setPlotFrame({ xDomain: [-XH, XH], yDomain: [-YH, YH], margin: m, draw: draw });
    UNIT = plotX(1) - plotX(0);
    FS = Math.max(7.5, Math.min(19, UNIT * 0.52));
  }

  /* ---------- primitives ---------- */
  function headPoly(g, tipx, tipy, ux, uy, len, color) {
    var bx = tipx - ux * len, by = tipy - uy * len, hw = len * 0.46;
    g.polygon([[tipx, tipy], [bx - uy * hw, by + ux * hw], [bx + uy * hw, by - ux * hw]])
      .fill(color).stroke('none');
  }

  function arrowWorld(g, x1, y1, x2, y2, color, width, headLen) {
    var p1x = plotX(x1), p1y = plotY(y1), p2x = plotX(x2), p2y = plotY(y2);
    var dx = p2x - p1x, dy = p2y - p1y, L = Math.sqrt(dx * dx + dy * dy);
    if (L < 1) return null;
    var ux = dx / L, uy = dy / L;
    var hl = Math.min(headLen, L * 0.75);
    g.line(p1x, p1y, p2x - ux * hl * 0.85, p2y - uy * hl * 0.85)
      .stroke({ color: color, width: width, linecap: 'butt' });
    headPoly(g, p2x, p2y, ux, uy, hl, color);
    var hit = g.line(p1x, p1y, p2x, p2y)
      .stroke({ color: '#000', width: Math.max(10, UNIT * 0.5), opacity: 0 });
    return hit;
  }

  function segWorld(g, x1, y1, x2, y2, color, width, dashed) {
    var l = g.line(plotX(x1), plotY(y1), plotX(x2), plotY(y2))
      .stroke({ color: color, width: width, linecap: 'round' });
    if (dashed) l.attr('stroke-dasharray', Math.max(3, UNIT * 0.16) + ',' + Math.max(3, UNIT * 0.14));
    return l;
  }

  function label(builder, wx, wy, size, color, halo) {
    var t = draw.text(builder).font({
      family: 'Georgia, "Times New Roman", serif',
      size: size, anchor: 'middle', leading: 1
    }).fill(color || '#111');
    if (halo !== false) {
      t.attr({ 'paint-order': 'stroke', stroke: '#ffffff', 'stroke-width': Math.max(2, size * 0.3), 'stroke-linejoin': 'round' });
    }
    var bb = t.bbox();
    t.attr('transform', 'translate(' + (plotX(wx) - bb.cx) + ',' + (plotY(wy) - bb.cy) + ')');
    return t;
  }

  function labelPx(builder, px, py, size, color, anchor) {
    var t = draw.text(builder).font({
      family: 'Helvetica, Arial, sans-serif', size: size, anchor: 'middle', leading: 1
    }).fill(color || '#555');
    t.attr({ 'paint-order': 'stroke', stroke: '#ffffff', 'stroke-width': Math.max(2, size * 0.3), 'stroke-linejoin': 'round' });
    var bb = t.bbox();
    var dx = px - bb.cx;
    if (anchor === 'start') dx = px - bb.x;
    if (anchor === 'end') dx = px - (bb.x + bb.width);
    t.attr('transform', 'translate(' + dx + ',' + (py - bb.cy) + ')');
    return t;
  }

  function vLabelBuilder(add) {
    add.tspan('v').font({ style: 'italic', weight: 'bold' });
    add.tspan(' = ');
    add.tspan('a').font({ style: 'italic' });
    add.tspan('i').font({ weight: 'bold' });
    add.tspan(' + ');
    add.tspan('b').font({ style: 'italic' });
    add.tspan('j').font({ weight: 'bold' });
  }

  /* ---------- main render ---------- */
  function render() {
    draw.clear();
    var mag = Math.sqrt(a * a + b * b);
    var axw = Math.max(0.7, UNIT * 0.045);
    var ahd = Math.max(5, UNIT * 0.32);
    var ox = plotX(0), oy = plotY(0);

    /* axes */
    var gx0 = plotX(-XH), gx1 = plotX(XH), gy0 = plotY(-YH), gy1 = plotY(YH);
    draw.line(gx0, oy, gx1, oy).stroke({ color: AXIS, width: axw });
    draw.line(ox, gy0, ox, gy1).stroke({ color: AXIS, width: axw });
    headPoly(draw, gx1, oy, 1, 0, ahd, AXIS);
    headPoly(draw, gx0, oy, -1, 0, ahd, AXIS);
    headPoly(draw, ox, gy1, 0, -1, ahd, AXIS);
    headPoly(draw, ox, gy0, 0, 1, ahd, AXIS);

    /* ticks */
    var tk = Math.max(3, UNIT * 0.19);
    for (var i = 2; i <= 12; i += 2) {
      if (i < XH - 0.4) {
        draw.line(plotX(i), oy - tk, plotX(i), oy + tk).stroke({ color: AXIS, width: axw });
        draw.line(plotX(-i), oy - tk, plotX(-i), oy + tk).stroke({ color: AXIS, width: axw });
      }
      if (i < YH - 0.4) {
        draw.line(ox - tk, plotY(i), ox + tk, plotY(i)).stroke({ color: AXIS, width: axw });
        draw.line(ox - tk, plotY(-i), ox + tk, plotY(-i)).stroke({ color: AXIS, width: axw });
      }
    }
    draw.circle(Math.max(2.5, UNIT * 0.09)).fill(AXIS).center(ox, oy);

    var vw = Math.max(1.6, UNIT * 0.085);
    var cw = Math.max(1.5, UNIT * 0.08);

    /* ----- components (navy) ----- */
    if (!triView) {
      var hitA = arrowWorld(draw, 0, 0, a, 0, NAVY, cw, ahd * 0.95);
      var hitB = arrowWorld(draw, a, 0, a, b, NAVY, cw, ahd * 0.95);
      if (hitA) {
        hitA.css('cursor', 'pointer')
          .on('mousemove', function (e) { showTooltip('Horizontal component  a i = ' + fmt(a) + ' i', e); })
          .on('mouseleave', hideTooltip)
          .on('click', function () { showPopup('The component a i', 'This dark blue arrow lies flat along the x-axis and carries the entire horizontal part of v. Its signed length is a: positive points right, negative points left. It contributes nothing vertical.'); });
      }
      if (hitB) {
        hitB.css('cursor', 'pointer')
          .on('mousemove', function (e) { showTooltip('Vertical component  b j = ' + fmt(b) + ' j', e); })
          .on('mouseleave', hideTooltip)
          .on('click', function () { showPopup('The component b j', 'This arrow starts at the head of a i — head to tail — and rises (or falls) by b. Because the two component arrows are chained, their sum lands exactly on the tip of v.'); });
      }
    } else {
      segWorld(draw, 0, 0, a, 0, NAVY, cw * 0.8, false);
      segWorld(draw, a, 0, a, b, NAVY, cw * 0.8, false);
      /* dashed guide from tip to the y-axis */
      segWorld(draw, a, b, 0, b, GRAY, Math.max(0.8, UNIT * 0.04), true);
      /* right-angle marker */
      var s = 0.38, dx = -sgn(a || 1) * s, dy = sgn(b || 1) * s;
      draw.polyline([
        [plotX(a + dx), plotY(0)],
        [plotX(a + dx), plotY(dy)],
        [plotX(a), plotY(dy)]
      ]).fill('none').stroke({ color: NAVY, width: Math.max(0.8, UNIT * 0.045) });
    }

    /* ----- resultant v (orange) ----- */
    var hitV = arrowWorld(draw, 0, 0, a, b, ORANGE, vw, ahd * 1.05);
    if (hitV) {
      hitV.css('cursor', 'pointer')
        .on('mousemove', function (e) { showTooltip('v = ' + fmt(a) + ' i + ' + fmt(b) + ' j   |v| = ' + mag.toFixed(2), e); })
        .on('mouseleave', hideTooltip)
        .on('click', function () { showPopup('The resultant v', 'v runs from the origin straight to the point (a, b). It is literally the head-to-tail sum of a i and b j, and it is the hypotenuse of the right triangle those two components make, so |v| = √(a² + b²).'); });
    }

    /* ----- labels ----- */
    var L = Math.max(mag, 1e-6);
    var nx = -b / L, ny = a / L;
    if (-(a * b) > 0) { nx = -nx; ny = -ny; }
    var off = 1.15;
    var lx = a / 2 + nx * off, ly = b / 2 + ny * off;
    lx = Math.max(-XH + 1.6, Math.min(XH - 1.6, lx));
    ly = Math.max(-YH + 0.7, Math.min(YH - 0.7, ly));

    if (!triView) {
      label(vLabelBuilder, lx, ly, FS * 1.02, '#111');
      if (Math.abs(a) > 0.01) {
        label(function (add) {
          add.tspan('a').font({ style: 'italic' });
          add.tspan('i').font({ weight: 'bold' });
        }, a / 2, (b >= 0 ? -0.62 : 0.62), FS, '#111');
      }
      if (Math.abs(b) > 0.01) {
        label(function (add) {
          add.tspan('b').font({ style: 'italic' });
          add.tspan('j').font({ weight: 'bold' });
        }, a + (a >= 0 ? 0.68 : -0.68), b / 2, FS, '#111');
      }
    } else {
      label(function (add) {
        add.tspan('|v| = √(a² + b²) = ' + mag.toFixed(2));
      }, lx, ly, FS * 0.92, ORANGE);
      if (Math.abs(a) > 0.01) {
        label(function (add) { add.tspan('|a| = ' + fmt(Math.abs(a))); },
          a / 2, (b >= 0 ? -0.62 : 0.62), FS * 0.88, NAVY);
      }
      if (Math.abs(b) > 0.01) {
        label(function (add) { add.tspan('|b| = ' + fmt(Math.abs(b))); },
          a + (a >= 0 ? 1.0 : -1.0), b / 2, FS * 0.88, NAVY);
      }
    }

    /* ----- legend (bottom-left) & readout (top-right) ----- */
    var lfs = Math.max(7, FS * 0.68);
    var lx0 = gx0 + lfs * 0.6, ly0 = gy0 - lfs * 2.4;
    var swl = lfs * 2.2;
    draw.line(lx0, ly0, lx0 + swl, ly0).stroke({ color: ORANGE, width: Math.max(1.4, lfs * 0.22) });
    labelPx(function (add) { add.tspan('resultant v'); }, lx0 + swl + lfs * 0.5, ly0, lfs, '#555', 'start');
    draw.line(lx0, ly0 + lfs * 1.5, lx0 + swl, ly0 + lfs * 1.5).stroke({ color: NAVY, width: Math.max(1.4, lfs * 0.22) });
    labelPx(function (add) { add.tspan('components a i , b j'); }, lx0 + swl + lfs * 0.5, ly0 + lfs * 1.5, lfs, '#555', 'start');

    labelPx(function (add) {
      add.tspan('a = ' + fmt(a) + '   b = ' + fmt(b) + '   |v| = ' + mag.toFixed(2));
    }, gx1 - lfs * 0.4, gy1 + lfs * 0.6, lfs, '#444', 'end');

    var ro = document.getElementById('liveReadout');
    if (ro) ro.textContent = 'a = ' + fmt(a) + ',  b = ' + fmt(b) + ',  |v| = ' + mag.toFixed(3);
  }

  function redraw() { configure(); render(); }

  /* ---------- interactions ---------- */
  window.update_aComponent = function (v) { a = v; render(); };
  window.update_bComponent = function (v) { b = v; render(); };
  window.toggle_viewMode = function (on) { triView = !!on; render(); };

  /* ---------- demo player ---------- */
  var steps = [
    { title: 'The vector and its parts', narration: 'An orange arrow v reaches into the first quadrant. Two dark blue arrows, a i along the x-axis and b j rising from its tip, are joined head to tail and land exactly on v\u2019s tip.', state: { a: 4, b: 3, tri: false } },
    { title: 'Stretch the horizontal part', narration: 'Increasing a lengthens only the a i arrow; the tip of v slides right and the vector tilts flatter, while b j is untouched.', state: { a: 6, b: 3, tri: false } },
    { title: 'Stretch the vertical part', narration: 'Now raise b. Only b j grows, the tip climbs, and v steepens \u2014 the two components act completely independently.', state: { a: 6, b: 6, tri: false } },
    { title: 'A negative component flips direction', narration: 'Set a negative and the a i arrow points left, carrying v into the second quadrant. The sum rule still holds: v always ends where b j ends.', state: { a: -3, b: 5, tri: false } },
    { title: 'Read off the magnitude', narration: 'Switch to the triangle view: the components become labeled legs with a right angle between them, and the hypotenuse is |v| = \u221a(a\u00b2 + b\u00b2).', state: { a: 4, b: 3, tri: true } },
    { title: 'Watch the hypotenuse respond', narration: 'Change either leg and the hypotenuse updates by the Pythagorean theorem \u2014 length depends on both components, but never on their signs.', state: { a: -4, b: 3, tri: true } }
  ];
  var cur = 0;

  function setStep(i) {
    cur = Math.max(0, Math.min(steps.length - 1, i));
    var st = steps[cur].state;
    a = st.a; b = st.b; triView = st.tri;
    var ai = document.getElementById('aComponentInput');
    var bi = document.getElementById('bComponentInput');
    var vi = document.getElementById('viewModeInput');
    if (ai) { ai.value = a; document.getElementById('aComponentVal').value = a; }
    if (bi) { bi.value = b; document.getElementById('bComponentVal').value = b; }
    if (vi) vi.checked = triView;
    var n = document.getElementById('demoNarration');
    if (n) n.textContent = steps[cur].narration;
    var sl = document.getElementById('stepLabel');
    if (sl) sl.textContent = 'Step ' + (cur + 1) + '/' + steps.length + ' \u00b7 ' + steps[cur].title;
    render();
  }
  window.nextStep = function () { setStep(cur + 1); };
  window.prevStep = function () { setStep(cur - 1); };

  document.addEventListener('fig-resize', function () { redraw(); });

  configure();
  setStep(0);
  window.__markRendered();
})();
// @FIGURE_CODE_END

